import{_ as t,o as d,c as o,a0 as a}from"./chunks/framework.BDx3ik-m.js";const h=JSON.parse('{"title":"EPIC 35: Promotion Code Quality — Deprecated Marking, JSDoc Fix, Rate Limit Wiring","description":"","frontmatter":{},"headers":[],"relativePath":"epics/EPIC_35_PROMOTION_CODE_QUALITY.md","filePath":"epics/EPIC_35_PROMOTION_CODE_QUALITY.md"}'),i={name:"epics/EPIC_35_PROMOTION_CODE_QUALITY.md"};function r(n,e,s,c,l,p){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="epic-35-promotion-code-quality-—-deprecated-marking-jsdoc-fix-rate-limit-wiring" tabindex="-1">EPIC 35: Promotion Code Quality — Deprecated Marking, JSDoc Fix, Rate Limit Wiring <a class="header-anchor" href="#epic-35-promotion-code-quality-—-deprecated-marking-jsdoc-fix-rate-limit-wiring" aria-label="Permalink to &quot;EPIC 35: Promotion Code Quality — Deprecated Marking, JSDoc Fix, Rate Limit Wiring&quot;">​</a></h1><hr><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><strong>Epic</strong></td><td>35</td></tr><tr><td><strong>Module</strong></td><td>promotion (<code>08-promotion.yaml</code>)</td></tr><tr><td><strong>Priority</strong></td><td>Medium</td></tr><tr><td><strong>Target SDK Version</strong></td><td>v2.7.x</td></tr><tr><td><strong>Backlog Task</strong></td><td>task-35</td></tr><tr><td><strong>Depends On</strong></td><td>None</td></tr><tr><td><strong>Source</strong></td><td>February 2026 Swagger Audit</td></tr><tr><td><strong>Related Stories</strong></td><td>4.5 (Promotion &amp; Tariffs Modules)</td></tr></tbody></table><hr><h2 id="problem-statement" tabindex="-1">Problem Statement <a class="header-anchor" href="#problem-statement" aria-label="Permalink to &quot;Problem Statement&quot;">​</a></h2><p>The February 2026 swagger audit of module <code>08-promotion</code> identified significant code quality gaps despite the module passing QA gates at 95/100. The SDK has 42 methods covering 42 of the 50 swagger endpoints (the other 8 being new — covered by EPIC 34), but the existing code has defects affecting developer experience, runtime correctness, and API compliance:</p><ol><li><p><strong>16 Deprecated Endpoints Not Marked</strong>: 16 endpoints are deprecated in swagger (32% deprecation rate!) but the SDK has zero <code>@deprecated</code> JSDoc tags and zero runtime warnings.</p></li><li><p><strong>1 Removed Endpoint</strong>: <code>POST /adv/v1/save-ad</code> has been completely removed from the swagger, but the SDK still has <code>createAdvSaveAd()</code> calling this non-existent endpoint.</p></li><li><p><strong>JSDoc @example Bug</strong>: All 42 <code>@example</code> blocks reference <code>sdk.general.*</code> instead of <code>sdk.promotion.*</code>. Copy-paste from JSDoc fails at runtime.</p></li><li><p><strong>Rate Limit Keys Not Wired</strong>: 42 rate limit configuration entries exist in <code>src/config/promotion-rate-limits.ts</code> but zero methods pass <code>rateLimitKey</code> to BaseClient. Rate limits are defined but never enforced.</p></li></ol><hr><h2 id="detailed-gap-analysis" tabindex="-1">Detailed Gap Analysis <a class="header-anchor" href="#detailed-gap-analysis" aria-label="Permalink to &quot;Detailed Gap Analysis&quot;">​</a></h2><h3 id="gap-1-deprecated-endpoints-16-methods" tabindex="-1">Gap 1: Deprecated Endpoints (16 methods) <a class="header-anchor" href="#gap-1-deprecated-endpoints-16-methods" aria-label="Permalink to &quot;Gap 1: Deprecated Endpoints (16 methods)&quot;">​</a></h3><p>The following 16 endpoints are deprecated in the swagger but have no <code>@deprecated</code> tag in the SDK:</p><table tabindex="0"><thead><tr><th>#</th><th>Deprecated Endpoint</th><th>SDK Method</th><th>Swagger Shard</th><th>Replacement</th></tr></thead><tbody><tr><td>1</td><td><code>POST /adv/v1/promotion/adverts</code></td><td><code>getAdvPromotionAdverts()</code></td><td>kampanii.yaml</td><td><code>GET /api/advert/v2/adverts</code></td></tr><tr><td>2</td><td><code>GET /adv/v1/promotion/count</code></td><td><code>getAdvPromotionCount()</code></td><td>kampanii.yaml</td><td>None specified</td></tr><tr><td>3</td><td><code>POST /adv/v1/save-ad</code></td><td><code>createAdvSaveAd()</code></td><td>sozdanie-kampaniy.yaml</td><td><strong>REMOVED from swagger</strong></td></tr><tr><td>4</td><td><code>POST /adv/v2/seacat/save-ad</code></td><td><code>createAdvSeacatSaveAd()</code></td><td>sozdanie-kampaniy.yaml</td><td>None specified</td></tr><tr><td>5</td><td><code>GET /adv/v0/start</code></td><td><code>getAdvStart()</code></td><td>upravlenie-kampaniyami.yaml</td><td>None specified</td></tr><tr><td>6</td><td><code>GET /adv/v0/pause</code></td><td><code>getAdvPause()</code></td><td>upravlenie-kampaniyami.yaml</td><td>None specified</td></tr><tr><td>7</td><td><code>GET /adv/v0/config</code></td><td><code>getAdvConfig()</code></td><td>parametry-kampaniy.yaml</td><td>None specified</td></tr><tr><td>8</td><td><code>GET /adv/v0/auction/adverts</code></td><td><code>getAdvAuctionAdverts()</code></td><td>parametry-kampaniy.yaml</td><td>None specified</td></tr><tr><td>9</td><td><code>POST /adv/v0/bids/min</code></td><td><code>createAdvBidsMin()</code></td><td>parametry-kampaniy.yaml</td><td><code>POST /api/advert/v1/bids/min</code></td></tr><tr><td>10</td><td><code>PATCH /adv/v0/bids</code></td><td><code>updateAdvBids()</code></td><td>parametry-kampaniy.yaml</td><td><code>PATCH /api/advert/v1/bids</code></td></tr><tr><td>11</td><td><code>POST /adv/v2/supplier/nms</code></td><td><code>createAdvSupplierNms()</code></td><td>parametry-kampaniy.yaml</td><td>None specified</td></tr><tr><td>12</td><td><code>GET /adv/v1/supplier/subjects</code></td><td><code>getAdvSupplierSubjects()</code></td><td>parametry-kampaniy.yaml</td><td>None specified</td></tr><tr><td>13</td><td><code>POST /adv/v1/fullstats</code></td><td><code>createAdvFullstats()</code></td><td>statistika.yaml</td><td>None specified</td></tr><tr><td>14</td><td><code>GET /adv/v1/stat/words</code></td><td><code>getAdvStatWords()</code></td><td>statistika.yaml</td><td>None specified</td></tr><tr><td>15</td><td><code>POST /adv/v2/auto/daily-words</code></td><td><code>createAdvAutoDailyWords()</code></td><td>statistika.yaml</td><td>None specified</td></tr><tr><td>16</td><td><code>GET /adv/v0/advert-list</code></td><td><code>getAdvAdvertList()</code></td><td>statistika.yaml</td><td>None specified</td></tr></tbody></table><p><strong>Required changes per method</strong>:</p><ol><li>Add <code>@deprecated</code> JSDoc tag with migration guidance (where replacement exists)</li><li>Add <code>console.warn()</code> on first invocation using a static flag per method (warn-once pattern)</li><li>Method must continue to function — deprecation is informational</li></ol><h3 id="gap-2-removed-endpoint-1-method" tabindex="-1">Gap 2: Removed Endpoint (1 method) <a class="header-anchor" href="#gap-2-removed-endpoint-1-method" aria-label="Permalink to &quot;Gap 2: Removed Endpoint (1 method)&quot;">​</a></h3><p><code>POST /adv/v1/save-ad</code> → <code>createAdvSaveAd()</code> — This endpoint has been completely removed from the swagger. The SDK method will fail with a 404 at runtime.</p><p><strong>Required changes</strong>:</p><ul><li>Mark with <code>@deprecated</code> and strong warning that endpoint is removed</li><li>Add <code>console.warn</code> noting the endpoint no longer exists</li><li>Consider adding a runtime check or alias to a replacement if one exists</li></ul><h3 id="gap-3-jsdoc-example-bug-20-methods" tabindex="-1">Gap 3: JSDoc @example Bug (20 methods) <a class="header-anchor" href="#gap-3-jsdoc-example-bug-20-methods" aria-label="Permalink to &quot;Gap 3: JSDoc @example Bug (20 methods)&quot;">​</a></h3><p>All 42 methods have <code>@example</code> blocks referencing <code>sdk.general.*</code> instead of <code>sdk.promotion.*</code>. This is the same code generation template bug found in other modules (in-store-pickup: 16, orders-fbw: 8).</p><p><strong>Fix</strong>: Replace all 42 occurrences of <code>sdk.general.</code> with <code>sdk.promotion.</code> in <code>@example</code> blocks.</p><h3 id="gap-4-rate-limit-keys-not-wired-42-methods" tabindex="-1">Gap 4: Rate Limit Keys Not Wired (42 methods) <a class="header-anchor" href="#gap-4-rate-limit-keys-not-wired-42-methods" aria-label="Permalink to &quot;Gap 4: Rate Limit Keys Not Wired (42 methods)&quot;">​</a></h3><p>The file <code>src/config/promotion-rate-limits.ts</code> defines 42 rate limit entries across 3 tiers:</p><ul><li><strong>Tier 1</strong>: 300-600 req/min (7 entries)</li><li><strong>Tier 2</strong>: 1-240 req/min (25 entries)</li><li><strong>Tier 3</strong>: 1-5 req/min (10 entries)</li></ul><p>None of the 42 module methods pass <code>rateLimitKey</code> to BaseClient. This means rate limits are defined but never enforced at runtime, putting users at risk of 429 errors and potential API blocks.</p><p><strong>Fix</strong>: Add <code>rateLimitKey</code> option to all 42 BaseClient calls using the config keys from <code>promotion-rate-limits.ts</code>.</p><hr><h2 id="implementation-approach" tabindex="-1">Implementation Approach <a class="header-anchor" href="#implementation-approach" aria-label="Permalink to &quot;Implementation Approach&quot;">​</a></h2><h3 id="step-1-fix-jsdoc-example-blocks" tabindex="-1">Step 1: Fix JSDoc @example Blocks <a class="header-anchor" href="#step-1-fix-jsdoc-example-blocks" aria-label="Permalink to &quot;Step 1: Fix JSDoc @example Blocks&quot;">​</a></h3><p>Replace all 42 occurrences of <code>sdk.general.</code> with <code>sdk.promotion.</code> in <code>src/modules/promotion/index.ts</code>.</p><h3 id="step-2-mark-16-deprecated-methods" tabindex="-1">Step 2: Mark 16 Deprecated Methods <a class="header-anchor" href="#step-2-mark-16-deprecated-methods" aria-label="Permalink to &quot;Step 2: Mark 16 Deprecated Methods&quot;">​</a></h3><p>Add <code>@deprecated</code> JSDoc tag and <code>console.warn()</code> (warn-once pattern) to all 16 deprecated methods. Group related static flags to avoid excessive class-level properties.</p><h3 id="step-3-handle-removed-endpoint" tabindex="-1">Step 3: Handle Removed Endpoint <a class="header-anchor" href="#step-3-handle-removed-endpoint" aria-label="Permalink to &quot;Step 3: Handle Removed Endpoint&quot;">​</a></h3><p>Mark <code>createAdvSaveAd()</code> with <code>@deprecated</code> and a strong removal warning. Add runtime <code>console.warn</code> noting the endpoint no longer exists in the API.</p><h3 id="step-4-wire-rate-limit-keys" tabindex="-1">Step 4: Wire Rate Limit Keys <a class="header-anchor" href="#step-4-wire-rate-limit-keys" aria-label="Permalink to &quot;Step 4: Wire Rate Limit Keys&quot;">​</a></h3><p>Add <code>rateLimitKey</code> option to all 42 BaseClient calls. Also add 9 new entries for EPIC 34 endpoints (total ~51).</p><h3 id="step-5-update-unit-tests" tabindex="-1">Step 5: Update Unit Tests <a class="header-anchor" href="#step-5-update-unit-tests" aria-label="Permalink to &quot;Step 5: Update Unit Tests&quot;">​</a></h3><p>Update <code>tests/unit/modules/promotion.test.ts</code> to:</p><ul><li>Verify rateLimitKey presence in all 42 method calls</li><li>Add deprecation warning tests for the 16 deprecated methods</li><li>Add removal warning test for createAdvSaveAd</li></ul><h3 id="step-6-verify-build-and-lint" tabindex="-1">Step 6: Verify Build and Lint <a class="header-anchor" href="#step-6-verify-build-and-lint" aria-label="Permalink to &quot;Step 6: Verify Build and Lint&quot;">​</a></h3><p>Run <code>npx tsc --noEmit</code> and <code>npm run lint</code> to ensure zero errors.</p><hr><h2 id="files-to-modify" tabindex="-1">Files to Modify <a class="header-anchor" href="#files-to-modify" aria-label="Permalink to &quot;Files to Modify&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Changes</th><th>Estimated Effort</th></tr></thead><tbody><tr><td><code>src/modules/promotion/index.ts</code></td><td>Fix 42 @example blocks, add 16 @deprecated tags + console.warn, handle 1 removed endpoint, add rateLimitKey to 42 methods</td><td>High</td></tr><tr><td><code>src/config/promotion-rate-limits.ts</code></td><td>Add 9 new entries for EPIC 34 endpoints</td><td>Low</td></tr><tr><td><code>tests/unit/modules/promotion.test.ts</code></td><td>Add rateLimitKey assertions, deprecation warning tests</td><td>Medium</td></tr></tbody></table><hr><h2 id="risk-assessment" tabindex="-1">Risk Assessment <a class="header-anchor" href="#risk-assessment" aria-label="Permalink to &quot;Risk Assessment&quot;">​</a></h2><p><strong>Overall Risk</strong>: MEDIUM (higher than FBW due to 16 deprecated methods and 42 rate limit wirings)</p><table tabindex="0"><thead><tr><th>Risk</th><th>Likelihood</th><th>Impact</th><th>Mitigation</th></tr></thead><tbody><tr><td>Deprecated warnings break CI</td><td>Low</td><td>Medium</td><td>Use warn-once pattern; mock console.warn in tests</td></tr><tr><td>Rate limit wiring changes behavior</td><td>Low</td><td>Medium</td><td>Rate limits are correct per swagger; prevents 429 errors</td></tr><tr><td>Removed endpoint handling</td><td>Medium</td><td>Low</td><td>Clear deprecation message; method still callable but will fail</td></tr><tr><td>20 JSDoc fixes break something</td><td>Very Low</td><td>Low</td><td>Text-only changes in comments</td></tr><tr><td>Many changes to one file</td><td>Medium</td><td>Medium</td><td>Careful testing; all changes are additive or comment-only</td></tr></tbody></table><hr><h2 id="success-criteria" tabindex="-1">Success Criteria <a class="header-anchor" href="#success-criteria" aria-label="Permalink to &quot;Success Criteria&quot;">​</a></h2><ul><li>[x] All 16 deprecated methods marked with <code>@deprecated</code> JSDoc tag and <code>console.warn</code> on first call</li><li>[x] <code>createAdvSaveAd()</code> marked as <code>@deprecated</code> (endpoint removed from swagger)</li><li>[x] All 42 JSDoc <code>@example</code> blocks reference <code>sdk.promotion.*</code> (not <code>sdk.general.*</code>)</li><li>[x] All 42 methods pass correct <code>rateLimitKey</code> from promotion-rate-limits config to BaseClient</li><li>[ ] Rate limit config updated with 9 new entries for EPIC 34 endpoints (total ~51)</li><li>[x] <code>npx tsc --noEmit</code> exits 0</li><li>[x] <code>npm run lint</code> exits 0</li><li>[x] All existing unit tests pass with zero regressions</li><li>[x] New unit tests for rateLimitKey and deprecation pass</li></ul><hr><h2 id="related-documents" tabindex="-1">Related Documents <a class="header-anchor" href="#related-documents" aria-label="Permalink to &quot;Related Documents&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Document</th><th>Path</th></tr></thead><tbody><tr><td>Swagger spec</td><td><code>wildberries_api_doc/08-promotion.yaml</code></td></tr><tr><td>Swagger shards</td><td><code>wildberries_api_doc/08-promotion/</code> (9 shards)</td></tr><tr><td>Module source</td><td><code>src/modules/promotion/index.ts</code> (808 lines)</td></tr><tr><td>Rate limit config</td><td><code>src/config/promotion-rate-limits.ts</code> (42 entries)</td></tr><tr><td>Types</td><td><code>src/types/promotion.types.ts</code></td></tr><tr><td>Unit tests</td><td><code>tests/unit/modules/promotion.test.ts</code> (643 lines)</td></tr><tr><td>Integration tests</td><td><code>tests/integration/promotion.integration.test.ts</code> (490 lines)</td></tr><tr><td>Story 4.5</td><td><code>docs/stories/4.5.promotion-tariffs-modules.md</code></td></tr><tr><td>QA Gate 4.5</td><td><code>docs/qa/gates/4.5-promotion-tariffs-modules.yml</code></td></tr><tr><td>EPIC 33 (types)</td><td><code>docs/epics/EPIC_33_PROMOTION_TYPE_EXPANSION.md</code></td></tr><tr><td>EPIC 34 (new endpoints)</td><td><code>docs/epics/EPIC_34_PROMOTION_NEW_ENDPOINTS.md</code></td></tr><tr><td>Backlog task (code quality)</td><td><code>backlog/tasks/task-35</code></td></tr></tbody></table><hr><h2 id="completion-status" tabindex="-1">Completion Status <a class="header-anchor" href="#completion-status" aria-label="Permalink to &quot;Completion Status&quot;">​</a></h2><p><strong>Status</strong>: COMPLETE (as of 2026-02-06)</p><h3 id="implementation-summary" tabindex="-1">Implementation Summary <a class="header-anchor" href="#implementation-summary" aria-label="Permalink to &quot;Implementation Summary&quot;">​</a></h3><ul><li>Marked all 16 deprecated methods with @deprecated JSDoc tag and console.warn (warn-once pattern)</li><li>Marked createAdvSaveAd() as deprecated (endpoint removed from swagger)</li><li>Fixed all 42 JSDoc @example blocks to reference sdk.promotion.* instead of sdk.general.*</li><li>Wired rateLimitKey to all 42 existing methods for proper rate limit enforcement</li><li>TypeScript strict mode passes</li><li>Linting passes</li><li>All existing unit tests pass with zero regressions</li><li>New unit tests added for rateLimitKey verification and deprecation warnings</li></ul><h3 id="remaining-items" tabindex="-1">Remaining Items <a class="header-anchor" href="#remaining-items" aria-label="Permalink to &quot;Remaining Items&quot;">​</a></h3><ul><li>Rate limit config entries for EPIC 34&#39;s 9 new endpoints (AC #5) - to be completed as part of EPIC 34 implementation</li></ul>',62)])])}const g=t(i,[["render",r]]);export{h as __pageData,g as default};
